new='''      renderLiveRulePanel({status:"source-unavailable",chapter99SourceAvailable:false,measures:[],unresolvedMatches:[],currentHts:lastRulePreview?.currentHts});\n      renderPgaPanel(baseData);\n    }\n'''
if old not in s: raise SystemExit('catch render marker missing')
s=s.replace(old,new,1)

